import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"本地模型（llama.cpp）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/local-models.md","filePath":"guide/local-models.md"}'),l={name:"guide/local-models.md"};function n(p,a,d,o,h,r){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="本地模型-llama-cpp" tabindex="-1">本地模型（llama.cpp） <a class="header-anchor" href="#本地模型-llama-cpp" aria-label="Permalink to &quot;本地模型（llama.cpp）&quot;">​</a></h1><p>nek 内置对 <a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> **路由服务（router）**的支持。路由服务能发现一个目录下的多个 GGUF 模型，并按需加载和卸载。</p><p>其他本地服务（Ollama、LM Studio、vLLM、SGLang 等）按 <a href="/nekcode/guide/models#compatible-endpoint">兼容接口</a> 写进 <code>models.json</code> 即可。</p><h2 id="启动路由服务" tabindex="-1">启动路由服务 <a class="header-anchor" href="#启动路由服务" aria-label="Permalink to &quot;启动路由服务&quot;">​</a></h2><p>使用支持 router 模式的较新 llama.cpp。可以按 <a href="https://github.com/ggml-org/llama.cpp/blob/master/docs/build.md" target="_blank" rel="noreferrer">官方构建说明</a> 编译，或下载对应平台的 <a href="https://github.com/ggml-org/llama.cpp/releases" target="_blank" rel="noreferrer">预编译版本</a>。</p><p>启动 <code>llama-server</code> 时<strong>不要</strong>传 <code>--model</code>、<code>-m</code> 或 <code>-hf</code>，否则会进入单模型模式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">llama-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --models-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/models</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --jinja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -ngl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 999</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32768</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>--models-dir ~/models</code></td><td>扫描这个目录下的 GGUF 文件</td></tr><tr><td><code>--jinja</code></td><td>启用兼容的对话模板和工具调用</td></tr><tr><td><code>-ngl 999</code></td><td>尽可能多地把层放到 GPU 上</td></tr><tr><td><code>-c 32768</code></td><td>每个加载的模型的上下文长度。省略时使用模型原生长度，可能需要多得多的显存/内存</td></tr><tr><td><code>--host 127.0.0.1</code></td><td>只允许本机访问</td></tr><tr><td><code>--no-models-autoload</code></td><td>可选。关闭“选中即加载”，模型需要你在路由服务上手动加载</td></tr></tbody></table><p>单文件模型可以直接放在模型目录下；多模态模型和分片模型放在各自的子目录里：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/models/</span></span>
<span class="line"><span>├── llama-3.2-1b-Q4_K_M.gguf</span></span>
<span class="line"><span>├── gemma-3-4b-it-Q4_K_M/</span></span>
<span class="line"><span>│   ├── gemma-3-4b-it-Q4_K_M.gguf</span></span>
<span class="line"><span>│   └── mmproj-F16.gguf</span></span>
<span class="line"><span>└── large-model-Q4_K_M/</span></span>
<span class="line"><span>    ├── large-model-Q4_K_M-00001-of-00003.gguf</span></span>
<span class="line"><span>    ├── large-model-Q4_K_M-00002-of-00003.gguf</span></span>
<span class="line"><span>    └── large-model-Q4_K_M-00003-of-00003.gguf</span></span></code></pre></div><p>手动添加文件后需要重启路由服务。每个模型单独的上下文长度等选项用 llama.cpp 的 <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md#model-presets" target="_blank" rel="noreferrer">model presets</a> 配置。</p><h2 id="在-nek-中连接" tabindex="-1">在 nek 中连接 <a class="header-anchor" href="#在-nek-中连接" aria-label="Permalink to &quot;在 nek 中连接&quot;">​</a></h2><p>在 nek 里运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login llama.cpp</span></span></code></pre></div><p>输入路由服务地址（默认 <code>http://127.0.0.1:8080</code>）和可选的 API key。然后用 <code>/model</code> 选择模型。</p><p>也可以用环境变量配置，不经过 <code>/login</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLAMA_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLAMA_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">optional-secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span></span></code></pre></div><p>如果路由服务设置了 API key，启动 <code>llama-server</code> 时用相同的 <code>--api-key</code>。</p><h2 id="选择和加载模型" tabindex="-1">选择和加载模型 <a class="header-anchor" href="#选择和加载模型" aria-label="Permalink to &quot;选择和加载模型&quot;">​</a></h2><ul><li>已加载和休眠中的模型会出现在 <code>/model</code> 里，休眠的模型被选中时自动唤醒。</li><li>开启自动加载（默认）时，未加载的预设模型也会出现，选中时加载。</li><li>使用了 <code>--no-models-autoload</code> 时，<code>/model</code> 只列出已加载的模型，需要先在路由服务上加载模型（例如通过 llama.cpp 自带的 Web 界面或它的 HTTP 接口）。</li></ul><p>路由服务可能同时被其他客户端使用，nek 显示的始终是路由服务当前的状态。</p><h2 id="排查问题" tabindex="-1">排查问题 <a class="header-anchor" href="#排查问题" aria-label="Permalink to &quot;排查问题&quot;">​</a></h2><p>先确认路由服务能访问：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/models</span></span></code></pre></div><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>路由服务里没有模型</td><td>检查 <code>--models-dir</code> 和目录结构，然后重启路由服务</td></tr><tr><td>用了 <code>--no-models-autoload</code>，<code>/model</code> 里看不到模型</td><td>先在路由服务上加载模型</td></tr><tr><td>加载失败或内存占用过高</td><td>调小 <code>-c</code>，或卸载其他模型</td></tr><tr><td>不是 router 模式</td><td>去掉 <code>--model</code>、<code>-m</code>、<code>-hf</code> 后重新启动</td></tr></tbody></table>`,25)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
